CustomField.formula:
IF(
                    MONTH(acpl__gf_event_date__c) < 4, '1Q' & TEXT(YEAR(acpl__gf_event_date__c)),
                    IF(
                                MONTH(acpl__gf_event_date__c) < 7, '2Q' & TEXT(YEAR(acpl__gf_event_date__c)),
                                IF(
                                                MONTH(acpl__gf_event_date__c) < 10, '3Q' & TEXT(YEAR(acpl__gf_event_date__c)),
                                                '4Q' & TEXT(YEAR(acpl__gf_event_date__c))
                                )
                )
)
